653	\begin{proposition}[Triangle inequality for ``$\simeq$"]\label{prop:simeq-triangle-inequality}
654			Suppose that $A$, $B$, $C$, and~$D$ are measurements such that
655			\begin{equation*}
656			A^x_a \ot I \simeq_{\eps} I \ot B^x_a,
657			\quad
658			C^x_a \ot I \simeq_{\delta} I \ot B^x_a,
659			\quad
660			C^x_a \ot I \simeq_{\gamma} I \ot D^x_a.
661			\end{equation*}
662			Then
663			\begin{equation*}
664			A^x_a \ot I \simeq_{\eps + 2\sqrt{\delta + \gamma}} I \ot D^x_a.
665			\end{equation*}
666			\end{proposition}
667	\begin{proof}
668	Because $B$, $C$, and~$D$ are measurements, \Cref{prop:simeq-to-approx} implies that
669	\begin{equation*}
670	C^x_a \ot I \approx_{2\delta} I \ot B^x_a,
671	\quad
672	C^x_a \ot I \approx_{2\gamma} I \ot D^x_a.
673	\end{equation*}
674	The triangle inequality, \Cref{prop:triangle-inequality-for-approx_delta}, then implies that
675	\begin{equation*}
676	I \ot B^x_a \approx_{4 \delta + 4 \gamma} I \ot D^x_a.
677	\end{equation*}
678	Finally, \Cref{prop:triangle-sub} implies that
679	\begin{equation*}
680	A^x_a \ot I
681	\simeq_{\eps + \sqrt{4 \delta + 4 \gamma}} I \ot D^x_a.
682	\end{equation*}
683	This completes the proof.
684	\end{proof}
