686	\begin{proposition}[Data processing for ``$\simeq$'']
687	\label{prop:simeq-data-processing}
688	Let $A = \{A^x_a\}$ and $B = \{B^x_a\}$ be two measurements such that
689	\begin{equation*}
690	A^x_a \ot I \simeq_{\delta} I \ot B^x_a.
 68	Now we apply \cref{thm:main-induction} to the symmetrized strategy.
 69	To do so, set
 70	\begin{align*}
 71	&1000k^2 m^2 \cdot\Big((3\eps)^{1/1024} + (3\eps)^{1/1024} + (3\eps)^{1/1024} + (d/q)^{1/1024}\Big)\\
 72	\leq{}& 10000 k^2 m^2 \cdot \Big(\eps^{1/1024} +  (d/q)^{1/1024}\Big)
 73	=: \nu,
 74	\end{align*}
 75	and set $\sigma = m^2\cdot\left(\nu + e^{-k/(80000m^2)}\right)$.
 76	Then \Cref{thm:main-induction} produces a measurement $G = \{G_g\} \in \polymeas{m}{q}{d}$ such that
 77	\begin{equation}\label{eq:just-applied-induction}
 78	(A_{\mathrm{sym}})^{u}_a \otimes I \simeq_{\sigma} I \otimes G_{[g(u)=a]}, \quad
 79	\text{and}
 80	\quad
 81	G_{[g(u)=a]} \otimes I \simeq_{\sigma} I \otimes (A_{\mathrm{sym}})^u_a.
 82	\end{equation}
 83	
 84	Now we unsymmetrize the symmetrized strategy
 85	to derive measurements $\{G^w_g\}$ for $w \in \{\mathrm{A},\mathrm{B}\}$.
 86	Letting $I_d$ denote the $d \times d$ identity operator, define the operators
 87	\begin{gather*}
 88	    G^{\mathrm{A}}_g = (\bra{0} \otimes I_d) \cdot G_g\cdot (\ket{0} \otimes I_d) \\
 89	    G^{\mathrm{B}}_g = (\bra{1} \otimes I_d) \cdot G_g\cdot (\ket{1} \otimes I_d),
 90	\end{gather*}
 91	where $\ket{0}$ and $\ket{1}$ act on the $\C^2$ part of $G_g$. Thus, $G^{\mathrm{A}}_g, G^{\mathrm{B}}_g$ are positive operators acting on $\C^d$, and furthermore they form POVMs:
 92	\[
 93	    \sum_g G^{\mathrm{A}}_g = \sum_g (\bra{0} \otimes I_d) \cdot G_g \cdot (\ket{0} \otimes I_d) = (\bra{0} \otimes I_d) \cdot \Big(\sum_g G_g\Big) \cdot (\ket{0} \otimes I_d) = I_d\;.
 94	\]
 95	The same derivation holds for $G^{\mathrm{B}}_g$. 
 96	
 97	Next we verify that the $\{G^{\mathrm{B}}_g\}$ measurements are consistent with the $\{A^{\mathrm{A},u}_a\}$ measurements:
 98	\begin{align*}
 99	    &\E_{\bu} \sum_{g,a \neq g(\bu)} \bra{\psi} A^{\mathrm{A},\bu}_a \otimes G^{\mathrm{B}}_g \ket{\psi} \notag \\
100	    ={}& \E_{\bu} \sum_{g,a \neq g(\bu)} \bra{\psi} A^{\mathrm{A},\bu}_a \otimes (\bra{1} \otimes I_d) \cdot G_g \cdot (\ket{1} \otimes I_d) \ket{\psi} \notag \\
101	    ={}& \E_{\bu} \sum_{g,a \neq g(\bu)} (\bra{0,1}_{\mathrm{A'B'}} \otimes \bra{\psi}_{\mathrm{AB}}) \cdot (A_{\mathrm{sym}})^{\bu}_a \otimes G_g \cdot (\ket{0,1}_{\mathrm{A'B'}} \otimes \ket{\psi}_{\mathrm{AB}}) \notag \\
102	    \leq{}& 2 \cdot \E_{\bu} \sum_{g,a \neq g(\bu)} \bra{\psi_{\mathrm{sym}}} (A_{\mathrm{sym}})^{\bu}_a \otimes G_g \ket{\psi_{\mathrm{sym}}} \notag \\
103	    \leq{}& 2\sigma. \tag{by \Cref{eq:just-applied-induction}}
104	\end{align*}
105	The first inequality follows from the fact that the cross-terms $\bra{0} (A_{\mathrm{sym}})_a^{u} \ket{1}$ and $\bra{1} (A_{\mathrm{sym}})_a^{u} \ket{0}$ vanish by construction of $A_{\mathrm{sym}}$.  Combined with a similar derivation for the $G^{\mathrm{A}}_g$ and $A^{\mathrm{B},u}_a$ operators, we deduce
106	\begin{gather}
107	    G^{\mathrm{A}}_{[g(u)=a]} \otimes I \simeq_{2\sigma} I \otimes A^{\mathrm{B},u}_a \label{eq:cons-a}\\
108	    I \otimes G^{\mathrm{B}}_{[g(u)=a]} \simeq_{2\sigma}  A^{\mathrm{A},u}_a \otimes I \label{eq:cons-b}
109	\end{gather}
110	In addition, because the original strategy is $(3\eps, 3\eps, 3\eps)$-good,
111	\begin{equation*}
112	A^{\mathrm{A},u}_a \otimes I \simeq_{3\eps} I \otimes A^{\mathrm{B},u}_a.
113	\end{equation*}
114	Hence, \Cref{prop:simeq-triangle-inequality} implies that
115	\begin{equation*}
116	G^{\mathrm{A}}_{[g(u)=a]} \otimes I \simeq_{2\sigma + 2\sqrt{3\eps + 2\sigma}} I \otimes G^{\mathrm{B}}_{[g(u)=a]}.
117	\end{equation*}
118	This implies that
119	\begin{align*}
120	2\sigma + 2\sqrt{3\eps + 2\sigma}
121	& \geq \E_{\bu} \sum_{a \neq b} \bra{\psi} G^{\mathrm{A}}_{[g(\bu) =a]} \ot G^{\mathrm{B}}_{[g(\bu) = b]} \ket{\psi}\\
122	& = \E_{\bu} \sum_{g \neq h}  \bone[g(\bu) \neq h(\bu)] \cdot \bra{\psi} G^{\mathrm{A}}_{g} \ot G^{\mathrm{B}}_{h} \ket{\psi}\\
123	& = \E_{\bu} \sum_{g \neq h}  \bra{\psi} G^{\mathrm{A}}_{g} \ot G^{\mathrm{B}}_{h} \ket{\psi}
124		- \E_{\bu} \sum_{g \neq h}  \bone[g(\bu) = h(\bu)] \cdot \bra{\psi} G^{\mathrm{A}}_{g} \ot G^{\mathrm{B}}_{h} \ket{\psi}\\
125	& \geq \E_{\bu} \sum_{g \neq h}  \bra{\psi} G^{\mathrm{A}}_{g} \ot G^{\mathrm{B}}_{h} \ket{\psi}
126		-  \sum_{g \neq h}  \frac{md}{q}\cdot \bra{\psi} G^{\mathrm{A}}_{g} \ot G^{\mathrm{B}}_{h} \ket{\psi} \tag{by Schwartz-Zippel}\\
127	& \geq \E_{\bu} \sum_{g \neq h}  \bra{\psi} G^{\mathrm{A}}_{g} \ot G^{\mathrm{B}}_{h} \ket{\psi} - \frac{md}{q}.
128	\end{align*}
129	Rearranging, we get
130	\begin{equation}\label{eq:G-self-consistency}
131	G^{\mathrm{A}}_g \otimes I \simeq_{\zeta_1} I \ot G^{\mathrm{B}}_g.
132	\end{equation}
133	where $\zeta_1 = 2\sigma + 2\sqrt{3\eps + 2\sigma} + md/q$.
134	
135	We have now derived everything we wanted, except that~$G$ is not necessarily projective.
136	To remedy this, we apply the orthogonalization lemma for measurements (\Cref{lem:orthonormalization-main-lemma})
137	to \Cref{eq:G-self-consistency}.
138	It implies the existence of two projective sub-measurements $P^{\mathrm{A}} = \{P^{\mathrm{A}}\}, P^{\mathrm{B}} = \{P^{\mathrm{B}}\} \in \polysub{m}{q}{d}$ such that
139	\begin{align*}
140	G^{\mathrm{A}}_g \ot I &\approx_{100\zeta_1^{1/4}} P^{\mathrm{A}}_g \ot I,\\
141	I \ot G^{\mathrm{B}}_g &\approx_{100\zeta_1^{1/4}} I \ot P^{\mathrm{B}}_g.
142	\end{align*}
143	Hence, \Cref{prop:completing-to-measurement} implies that we can complete $P^{\mathrm{A}}$ and~$P^{\mathrm{B}}$ to projective measurements
144	$Q^{\mathrm{A}} = \{Q^{\mathrm{A}}\}, Q^{\mathrm{B}} = \{Q^{\mathrm{B}}\} \in \polymeas{m}{q}{d}$ such that
145	\begin{align}
146	G^{\mathrm{A}}_g \ot I &\approx_{\zeta_2} Q^{\mathrm{A}}_g \ot I,\label{eq:G-with-Q-A}\\
147	I \ot G^{\mathrm{B}}_g &\approx_{\zeta_2} I \ot Q^{\mathrm{B}}_g.\nonumber
148	\end{align}
149	where $\zeta_2= 200\zeta_1^{1/4} + 40\zeta_1^{1/8}$.
150	Now,  \Cref{eq:G-self-consistency} and \Cref{prop:simeq-to-approx} imply that
151	\begin{equation*}
152	G^{\mathrm{A}}_g \otimes I \approx_{2\zeta_1} I \ot G^{\mathrm{B}}_g.
153	\end{equation*}
154	By the triangle inequality (\Cref{prop:triangle-inequality-for-approx_delta}),
155	\begin{equation*}
156	Q_g^{\mathrm{A}} \ot I \approx_{\zeta_3} I \ot Q_g^{\mathrm{B}},
157	\end{equation*}
158	where $\zeta_3 = 6\zeta_1 + 6\zeta_2$.
159	Because both of these measurements are projective, \Cref{prop:simeq-to-approx} then implies that
160	\begin{equation}\label{eq:third-goal}
161	Q_g^{\mathrm{A}} \ot I \simeq_{\zeta_3/2} I \ot Q_g^{\mathrm{B}},
162	\end{equation}
163	By the data processing inequality (\Cref{prop:simeq-data-processing}),
164	\begin{equation}\label{eq:just-data-processed-the-heck-outta-this}
165	Q_{[g(u)=a]}^{\mathrm{A}} \ot I \simeq_{\zeta_3/2} I \ot Q_{[g(u)=a]}^{\mathrm{B}},
166	\end{equation}
167	Next, \Cref{prop:triangle-sub}, applied to \Cref{eq:G-self-consistency} and \Cref{eq:G-with-Q-A} implies that
168	\begin{equation*}
169	Q^{\mathrm{A}}_g \otimes I \simeq_{\zeta_1} I \ot G^{\mathrm{B}}_g.
170	\end{equation*}
171	By data processing (\Cref{prop:simeq-data-processing}),
172	\begin{equation}\label{eq:ok-almost-there-ok}
173	Q^{\mathrm{A}}_{[g(u)=a]} \otimes I \simeq_{\zeta_1} I \ot G^{\mathrm{B}}_{[g(u)=a]}.
174	\end{equation}
175	Now we apply the triangle inequality (\Cref{prop:simeq-triangle-inequality})
176	to \Cref{eq:cons-b,eq:ok-almost-there-ok,eq:just-data-processed-the-heck-outta-this},
177	which implies that
178	\begin{equation}\label{eq:one-goal}
179	A^{\mathrm{A},u}_a \ot I \simeq_{\zeta_4} I \ot Q^{\mathrm{B}}_{[g(u)=a]},
180	\end{equation}
181	where $\zeta_4 = 2\sigma + 2 \sqrt{\zeta_1 + \zeta_3/2}$.
182	A similar argument shows that
183	\begin{equation}\label{eq:another-goal}
184	I \ot A^{\mathrm{B},u}_a \simeq_{\zeta_4} Q^{\mathrm{A}}_{[g(u)=a]} \ot I.
185	\end{equation}
